#include <bits/stdc++.h>
using namespace std;
const int INF = 0x7f7f7f7f;
int n, m, s, t, p, c, d, u[505], v[505];
int mxf, mnc;
int cnt = 1, lst[5000005], nxt[5000005<<1], too[5000005<<1], flow[5000005<<1], wgt[5000005<<1];
int dis[5000005], pre[5000005], la[5000005], fl[5000005];
bool inq[5000005];

void ae(int x, int y, int z, int w) {
    nxt[++cnt] = lst[x];
    too[cnt] = y;
    flow[cnt] = z;
    wgt[cnt] = w;
    lst[x] = cnt;
}

bool spfa() {
    fill(dis, dis + 5000005, INF);
    fill(inq, inq + 5000005, false);
    queue<int> q;
    q.push(s);
    inq[s] = true;
    dis[s] = 0;
    fl[s] = INF;
    pre[t] = -1;
    while (!q.empty()) {
        int x = q.front(); q.pop();
        inq[x] = false;
        for (int i = lst[x]; i; i = nxt[i]) {
            if (flow[i] && dis[too[i]] > dis[x] + wgt[i]) {
                dis[too[i]] = dis[x] + wgt[i];
                pre[too[i]] = x;
                la[too[i]] = i;
                fl[too[i]] = min(fl[x], flow[i]);
                if (!inq[too[i]]) {
                    inq[too[i]] = true;
                    q.push(too[i]);
                }
            }
        }
    }
    return pre[t] != -1;
}

void mcmf() {
    mxf = mnc = 0;
    while (spfa()) {
        int cur = t;
        mxf += fl[t];
        mnc += fl[t] * dis[t];
        while (cur != s) {
            flow[la[cur]] -= fl[t];
            flow[la[cur] ^ 1] += fl[t];
            cur = pre[cur];
        }
    }
}

int id(int time, int city) {
    return time * n + city;
}

int main() {
    cin >> n >> m >> p >> c >> d;
    s = 0;
    t = n * 99 + 1;
    for (int i = 1, tmp; i <= p && cin >> tmp; i++) {
        ae(s, id(0, tmp), 1, 0);
        ae(id(0, tmp), s, 0, 0);
    }
    for (int i = 1; i <= m; i++) cin >> u[i] >> v[i];
    for (int time = 0; time <= 99; time++) {
        ae(id(time, 1), id(time + 1, 1), INF, 0);
        ae(id(time + 1, 1), id(time, 1), 0, 0);
        for (int city = 2; city <= n; city++) {
            ae(id(time, city), id(time + 1, city), INF, c);
            ae(id(time + 1, city), id(time, city), 0, -c);
        }
        for (int j = 1; j <= m; j++) {
            for (int k = 1; k <= p; k++) {
                int cost = d * k * k - d * (k - 1) * (k - 1) + c;
                ae(id(time, u[j]), id(time + 1, v[j]), 1, cost);
                ae(id(time + 1, v[j]), id(time, u[j]), 0, -cost);
                ae(id(time, v[j]), id(time + 1, u[j]), 1, cost);
                ae(id(time + 1, u[j]), id(time, v[j]), 0, -cost);
            }
        }
    }
    mcmf();
    cout << mnc << endl;
    return 0;
}
